{"path": "units/csvfix/impl.py", "content": "import csv


def parse(line):
    """按 CSV 语义解析一行：去空白、支持引号，列数必须是 3，否则返回 None。"""
    try:
        fields = next(csv.reader([line]))
    except (csv.Error, StopIteration):
        return None
    fields = [field.strip() for field in fields]
    if len(fields) != 3:
        return None
    return fields


def total(rows):
    """累加每行第三列的金额（整数）。空字段跳过，非法数字抛 ValueError。"""
    total_amount = 0
    for row in rows:
        if len(row) < 3:
            continue
        raw = row[2].strip()
        if not raw:
            continue
        total_amount += int(raw)
    return total_amount
"}

{"path": "units/rules/engine.py", "content": "def evaluate(rules, facts):
    """求值规则：``{"all": [...]}`` 需要全部为真，``{"any": [...]}`` 需要至少一个为真。

    缺失的 fact 视为 False。两种键同时出现时以 ``all`` 优先。
    """
    if "all" in rules:
        return all(bool(facts.get(name, False)) for name in rules["all"])
    if "any" in rules:
        return any(bool(facts.get(name, False)) for name in rules["any"])
    return False
"}

{"path": "units/ledger/ledger.py", "content": """"一个只关心单个账户的小账本。"""


class Ledger:
    def apply(self, rows, op):
        """筛选出 account == op 的行（保持原顺序）；金额为负时抛 ValueError。"""
        selected = []
        for kind, account, cents in rows:
            if cents < 0:
                raise ValueError("negative amount: %r" % (cents,))
            if account == op:
                selected.append((kind, account, cents))
        return selected


def balance(rows, account):
    """该账户的净额：deposit 相加、withdraw 相减；没有该账户的行时返回 0。"""
    total = 0
    for kind, acct, cents in rows:
        if acct != account:
            continue
        if kind == "deposit":
            total += cents
        elif kind == "withdraw":
            total -= cents
        else:
            raise ValueError("unknown kind: %r" % (kind,))
    return total
"}

{"path": "units/schedule/schedule.py", "content": """"闭区间的时间段工具。"""


def slots(ranges, minutes):
    """合并闭区间：两段之间的空隙（next_lo - prev_hi）小于 minutes 视为同一段。

    返回按起点升序的合并结果；空输入返回 []。
    """
    if not ranges:
        return []
    ordered = sorted((tuple(r) for r in ranges), key=lambda r: r[0])
    merged = [list(ordered[0])]
    for lo, hi in ordered[1:]:
        prev = merged[-1]
        if lo - prev[1] < minutes:
            if hi > prev[1]:
                prev[1] = hi
        else:
            merged.append([lo, hi])
    return [tuple(seg) for seg in merged]


def overlaps(a, b):
    """两个闭区间是否有交叠；端点正好相接（如 (0,10) 与 (10,20)）不算交叠。"""
    return a[0] < b[1] and b[0] < a[1]
