{"path": "units/intervals/intervals.py", "content": """"闭区间工具（整数端点，lo <= hi）。"""


class Impl:
    def merge(self, ranges, gap=0):
        """合并闭区间：按 lo 排序后，若相邻两段之间缺失的整数个数
        （next.lo - prev.hi - 1）小于等于 gap 就合并。返回升序列表；空输入返回 []。
        """
        if not ranges:
            return []
        ordered = sorted((tuple(r) for r in ranges), key=lambda r: r[0])
        merged = [list(ordered[0])]
        for lo, hi in ordered[1:]:
            prev = merged[-1]
            if lo - prev[1] - 1 <= gap:
                if hi > prev[1]:
                    prev[1] = hi
            else:
                merged.append([lo, hi])
        return [tuple(seg) for seg in merged]

    def subtract(self, ranges, hole):
        """从 ranges 中挖去闭区间 hole，返回剩下的闭区间（升序）。"""
        hlo, hhi = hole
        result = []
        for lo, hi in self.merge(ranges):
            if hhi < lo or hlo > hi:
                result.append((lo, hi))
                continue
            if lo < hlo:
                result.append((lo, hlo - 1))
            if hi > hhi:
                result.append((hhi + 1, hi))
        result.sort()
        return result

    def total_length(self, ranges):
        """ranges 覆盖的整数个数之和（重叠只算一次）。"""
        return sum(hi - lo + 1 for lo, hi in self.merge(ranges))
"}

{"path": "units/flags/flags.py", "content": """"命令行风格的参数解析。"""


class Impl:
    def parse(self, argv):
        """返回 {"values": {...}, "flags": {...}, "positional": [...]}。"""
        values = {}
        flags = {}
        positional = []
        i = 0
        n = len(argv)
        while i < n:
            token = argv[i]
            if token == "--":
                positional.extend(argv[i + 1:])
                break
            if token.startswith("--"):
                body = token[2:]
                if "=" in body:
                    key, val = body.split("=", 1)
                    values.setdefault(key, []).append(val)
                    i += 1
                    continue
                key = body
                if i + 1 < n and not argv[i + 1].startswith("--"):
                    values.setdefault(key, []).append(argv[i + 1])
                    i += 2
                else:
                    flags[key] = True
                    i += 1
                continue
            if token.startswith("-") and token != "-":
                for ch in token[1:]:
                    flags[ch] = True
                i += 1
                continue
            positional.append(token)
            i += 1
        return {"values": values, "flags": flags, "positional": positional}
"}

{"path": "units/measure/measure.py", "content": "class Impl:
    _TO_CM = {"m": 100.0, "cm": 1.0, "mm": 0.1}

    def to_cm(self, value, unit):
        """把 value（单位 unit）换算成厘米；非法单位抛 ValueError。"""
        try:
            factor = self._TO_CM[unit]
        except KeyError:
            raise ValueError("unknown unit: %r" % (unit,))
        result = value * factor
        if result == int(result):
            return int(result)
        return result
"}

{"path": "units/slugify/slugify.py", "content": "import re


class Impl:
    _NON_ALNUM = re.compile(r"[^a-z0-9]+")

    def slugify(self, text):
        """小写化、把非字母数字折叠成单个 '-'、去首尾 '-'；空结果返回 'untitled'。"""
        slug = self._NON_ALNUM.sub("-", text.lower()).strip("-")
        return slug or "untitled"
